using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace CoastalFactory.Editor {public static partial class LeftFactoryDistrictBuilder {
const string ContinuousGroundFolder="Assets/_Anseong/Art/Environment/ContinuousPlantGround";
[MenuItem("Anseong/Art/Export Continuous Ground Obstacles")]
public static void ExportContinuousGroundObstacles(){EditorSceneManager.OpenScene(Scene);var root=GameObject.Find("Factory_HighlightedLZone");var plan=new SurfacePlan();foreach(var t in root.GetComponentsInChildren<Transform>()){if(!t.gameObject.activeInHierarchy||!PrefabUtility.IsOutermostPrefabInstanceRoot(t.gameObject))continue;var b=B(t.gameObject);if(b.size.x<.5f||b.size.z<.5f)continue;plan.areas.Add(ZoneBox(0,b,3));}Directory.CreateDirectory("Tools/ContinuousPlantGround");File.WriteAllText("Tools/ContinuousPlantGround/obstacles.json",JsonUtility.ToJson(plan));Debug.Log("CONTINUOUS_GROUND_OBSTACLES count="+plan.areas.Count);}
[MenuItem("Anseong/Art/Apply Continuous Plant Ground")]
public static void ApplyContinuousPlantGround(){EditorSceneManager.OpenScene(Scene);if(GameObject.Find("Ground_ContinuousRoadBasedDesign"))throw new Exception("Already applied");Folder(ContinuousGroundFolder);var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/QuaySurfaceDesign/04_CraneApron_LightSlabs.mat");string[] names={"01_Continuous_PaleConcrete","02_WarmLight_WorkingConcrete","03_CoolLight_HeavyDutyConcrete","04_LightGrey_ServicePaving","05_Roadside_GreenVerge","06_Pale_CurbAndWalkway"};Color[] colors={new Color(1.15f,1.15f,1.12f),new Color(1.16f,1.14f,1.08f),new Color(1.07f,1.12f,1.14f),new Color(1.06f,1.08f,1.07f),new Color(.28f,.36f,.18f),new Color(.76f,.77f,.72f)};var mats=new Material[6];for(int i=0;i<6;i++){Material m;if(i<4){m=new Material(source);m.SetColor("_BaseColor",colors[i]);m.SetFloat("_Pattern",i==3?1:0);m.SetFloat("_TileSize",i==3?1.5f:10);m.SetFloat("_SlabSize",i==0?12:i==1?15:10);m.SetFloat("_JointStrength",i==3?0:.035f);m.SetFloat("_DustStrength",.008f);m.SetFloat("_Contrast",.22f);m.SetFloat("_Brightness",1.25f);m.SetFloat("_Saturation",.04f);}else{m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.SetColor("_BaseColor",colors[i]);m.SetFloat("_Smoothness",0);m.enableInstancing=true;}m.name=names[i];AssetDatabase.CreateAsset(m,ContinuousGroundFolder+"/"+names[i]+".mat");mats[i]=m;}
foreach(var name in new[]{"ContinuousLandSurface","IndustrialApron_BaseMaterialOnly"}){var r=GameObject.Find(name).GetComponent<MeshRenderer>();var slots=r.sharedMaterials;for(int i=0;i<slots.Length;i++)slots[i]=mats[0];r.sharedMaterials=slots;}
var oldZones=GameObject.Find("Ground_FunctionalSurfaceZones");if(oldZones)oldZones.GetComponent<MeshRenderer>().enabled=false;var oldFactory=GameObject.Find("Factory_FivePavingZones");if(oldFactory)oldFactory.SetActive(false);
// Existing quay materials keep their different surface patterns, but join the light palette.
foreach(var guid in AssetDatabase.FindAssets("t:Material",new[]{"Assets/_Anseong/Art/Environment/QuaySurfaceDesign"})){var path=AssetDatabase.GUIDToAssetPath(guid);var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m.HasProperty("_Brightness"))continue;float k=m.name.StartsWith("01_")?.91f:m.name.StartsWith("02_")?.98f:1.05f;m.SetColor("_BaseColor",new Color(k,k*1.005f,k*.99f));m.SetFloat("_Contrast",.27f);m.SetFloat("_Brightness",1.25f);m.SetFloat("_DustStrength",.008f);m.SetFloat("_JointStrength",m.name.StartsWith("01_")?0:.075f);EditorUtility.SetDirty(m);}
var asphalt=AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/Asphalt.mat");if(asphalt){asphalt.SetColor("_BaseColor",new Color(.10f,.11f,.115f));EditorUtility.SetDirty(asphalt);}
var data=JsonUtility.FromJson<RoadResult>(File.ReadAllText("Tools/ContinuousPlantGround/ground_design.json"));var vertices=new List<Vector3>();var indices=new List<int>[6];for(int i=0;i<6;i++)indices[i]=new List<int>();foreach(var layer in data.layers)for(int j=0;j<layer.xy.Length;j+=6){int n=vertices.Count;float y=layer.channel==4?.027f:layer.channel==5?.030f:.021f;for(int k=0;k<3;k++)vertices.Add(new Vector3(layer.xy[j+k*2],y,layer.xy[j+k*2+1]));indices[layer.channel].AddRange(new[]{n,n+2,n+1});}var mesh=new Mesh{name="RoadBasedContinuousGround",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(vertices);mesh.subMeshCount=6;for(int i=0;i<6;i++)mesh.SetTriangles(indices[i],i);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,ContinuousGroundFolder+"/RoadBasedContinuousGround.asset");var root=new GameObject("Ground_ContinuousRoadBasedDesign");root.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=root.AddComponent<MeshRenderer>();renderer.sharedMaterials=mats;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;
File.WriteAllText(ContinuousGroundFolder+"/DesignGuide.md",data.report+"\nVisual reference: supplied aerial steelworks photo and POSCO official Pohang/Gwangyang overview photographs. https://posco.co.kr/homepage/docs/kor7/jsp/common/posco/s91a1000012c.jsp\nBuilding-footprint material rectangles are disabled, while their meshes remain available for rollback. Existing screening-tree children remain active. Base floors share one pale concrete. Subtle light paving variations follow road-delimited factory parcels, never individual building boxes. Roadside green strips and pale walk/curb bands follow the curved road geometry and exclude buildings, roads and the combat core. No new bitmap textures or shaders; existing quay shader and compressed grain map reused. One combined six-submesh ground renderer. Greenery uses solid opaque geometry, no grass blades, colliders or runtime scripts. VR performance unmeasured.\n");AssetDatabase.SaveAssets();AssetDatabase.Refresh();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);Debug.Log("CONTINUOUS_GROUND_PASS vertices="+vertices.Count+" buildingMaterialRectangles=0 newTextures=0 extraRenderers=1");}
public static void CompactContinuousGroundMesh(){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(ContinuousGroundFolder+"/RoadBasedContinuousGround.asset");var old=mesh.vertices;var vertices=new List<Vector3>();var lookup=new Dictionary<Vector3,int>();var indices=new List<int>[mesh.subMeshCount];for(int sub=0;sub<indices.Length;sub++){indices[sub]=new List<int>();foreach(var index in mesh.GetTriangles(sub)){var p=old[index];if(!lookup.TryGetValue(p,out int mapped)){mapped=vertices.Count;lookup.Add(p,mapped);vertices.Add(p);}indices[sub].Add(mapped);}}int before=old.Length;var replacement=new Mesh{name=mesh.name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};replacement.SetVertices(vertices);replacement.subMeshCount=indices.Length;for(int i=0;i<indices.Length;i++)replacement.SetTriangles(indices[i],i);replacement.RecalculateNormals();replacement.RecalculateBounds();EditorUtility.CopySerialized(replacement,mesh);Object.DestroyImmediate(replacement);EditorUtility.SetDirty(mesh);AssetDatabase.SaveAssets();Debug.Log("CONTINUOUS_GROUND_COMPACT_PASS before="+before+" after="+vertices.Count);}}}
